unint32 i;
int valid = 1;
adcs_vec3_t h = {0, 0, 0};
adcs_vec3_t parallel_part = {0, 0, 0};
adcs_vec3_t dumpable = {0, 0, 0};
double dumpable_mag = 0.0;
double b2 = 0.0, bnorm = 0.0, proj = 0.0;
adcs_actuator_command_t cmd;
adcs_vec3_t torque = {0, 0, 0};

cmd.command = (adcs_vec3_t){0, 0, 0};
cmd.saturated_axes = 0U;

if ((wd_input.enable != 0) && (wd_input.enable != 1))
    valid = 0;
if (wd_input.wheel_count != 4U)
    valid = 0;
if (wd_input.wheels == NULL)
    valid = 0;
if ((!isfinite(wd_config.start_nms)) || (!isfinite(wd_config.stop_nms)))
    valid = 0;
if (!((wd_config.stop_nms >= 0.0) && (wd_config.stop_nms < wd_config.start_nms)))
    valid = 0;
if ((!isfinite(wd_config.max_wheel_speed_rad_s)) || (wd_config.max_wheel_speed_rad_s <= 0.0))
    valid = 0;
if ((!isfinite(wd_config.gain_s_inv)) || (wd_config.gain_s_inv < 0.0))
    valid = 0;
if ((!isfinite(wd_config.max_dipole_a_m2)) || (wd_config.max_dipole_a_m2 < 0.0))
    valid = 0;
if ((wd_config.required_high < 1U) || (wd_config.required_high > 100U))
    valid = 0;
if ((wd_config.required_low < 1U) || (wd_config.required_low > 100U))
    valid = 0;
if ((wd_config.minimum_dump_cycles < 1U) || (wd_config.minimum_dump_cycles > 100U))
    valid = 0;
if ((wd_config.cooldown_cycles < 1U) || (wd_config.cooldown_cycles > 100U))
    valid = 0;

if ((!valid) || (wd_input.enable == 0)) {
    wd_state.mode = (valid ? WD_OFF : WD_FAULT);
    wd_state.high_cycles = 0U;
    wd_state.low_cycles = 0U;
    wd_state.elapsed = 0U;
    wd_output.mode = wd_state.mode;
    wd_output.momentum_nms = (adcs_vec3_t){0, 0, 0};
    wd_output.parallel_momentum_nms = (adcs_vec3_t){0, 0, 0};
    wd_output.dumpable_momentum_nms = (adcs_vec3_t){0, 0, 0};
    wd_output.dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
    wd_output.torque_nm = (adcs_vec3_t){0, 0, 0};
    wd_output.dumpable_magnitude_nms = 0.0;
    wd_output.high_cycles = 0U;
    wd_output.low_cycles = 0U;
    wd_output.elapsed = 0U;
    wd_output.saturation_mask = 0U;
    return;
}

if ((wd_input.field_body_t == NULL) || (!adcs_is_finite_vec3(wd_input.field_body_t)))
    valid = 0;
if (valid) {
    b2 = adcs_vec3_dot(wd_input.field_body_t, wd_input.field_body_t);
    bnorm = sqrt(b2);
    if ((!isfinite(bnorm)) || (bnorm <= ADCS_EPS_NORM))
        valid = 0;
}
if (valid) {
    for (i = 0U; i < 4U; i++) {
        adcs_vec3_t axis;
        if ((!isfinite(wd_input.wheels[i].inertia_kg_m2)) ||
            (!isfinite(wd_input.wheels[i].speed_rad_s)) ||
            (wd_input.wheels[i].inertia_kg_m2 < 0.0))
            valid = 0;
        if (fabs(wd_input.wheels[i].speed_rad_s) > wd_config.max_wheel_speed_rad_s)
            valid = 0;
        if (adcs_vec3_normalize(&wd_input.wheels[i].axis_body, ADCS_EPS_NORM, &axis) != ADCS_OK)
            valid = 0;
        if (!valid)
            break;
    }
}

if (valid &&
    (adcs_wheel_momentum(wd_input.wheels, wd_input.wheel_count, &h) != ADCS_OK))
    valid = 0;

if (!valid) {
    wd_state.mode = WD_FAULT;
    wd_state.high_cycles = 0U;
    wd_state.low_cycles = 0U;
    wd_state.elapsed = 0U;
    wd_output.mode = WD_FAULT;
    wd_output.momentum_nms = (adcs_vec3_t){0, 0, 0};
    wd_output.parallel_momentum_nms = (adcs_vec3_t){0, 0, 0};
    wd_output.dumpable_momentum_nms = (adcs_vec3_t){0, 0, 0};
    wd_output.dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
    wd_output.torque_nm = (adcs_vec3_t){0, 0, 0};
    wd_output.dumpable_magnitude_nms = 0.0;
    wd_output.high_cycles = 0U;
    wd_output.low_cycles = 0U;
    wd_output.elapsed = 0U;
    wd_output.saturation_mask = 0U;
    return;
}

proj = adcs_vec3_dot(&h, wd_input.field_body_t) / b2;
parallel_part = adcs_vec3_scale(wd_input.field_body_t, proj);
dumpable = adcs_vec3_sub(&h, &parallel_part);
dumpable_mag = adcs_vec3_norm(&dumpable);
if (!isfinite(dumpable_mag))
    dumpable_mag = 0.0;

switch (wd_state.mode) {
case WD_OFF:
case WD_ARMING:
    wd_state.elapsed = 0U;
    wd_state.low_cycles = 0U;
    if (dumpable_mag >= wd_config.start_nms) {
        if (wd_state.high_cycles < 0xFFFFFFFFU)
            wd_state.high_cycles++;
    } else {
        wd_state.high_cycles = 0U;
    }
    if (wd_state.high_cycles >= wd_config.required_high) {
        wd_state.mode = WD_DUMPING;
        wd_state.high_cycles = 0U;
        wd_state.low_cycles = 0U;
        wd_state.elapsed = 0U;
    } else {
        wd_state.mode = WD_ARMING;
    }
    break;
case WD_DUMPING:
    if (wd_state.elapsed < 0xFFFFFFFFU)
        wd_state.elapsed++;
    if (wd_state.elapsed >= wd_config.minimum_dump_cycles) {
        if (dumpable_mag <= wd_config.stop_nms) {
            if (wd_state.low_cycles < 0xFFFFFFFFU)
                wd_state.low_cycles++;
        } else {
            wd_state.low_cycles = 0U;
        }
    }
    if (wd_state.low_cycles >= wd_config.required_low) {
        wd_state.mode = WD_COOLDOWN;
        wd_state.high_cycles = 0U;
        wd_state.low_cycles = 0U;
        wd_state.elapsed = 0U;
    }
    break;
case WD_COOLDOWN:
    if (wd_state.elapsed < 0xFFFFFFFFU)
        wd_state.elapsed++;
    if (wd_state.elapsed >= wd_config.cooldown_cycles) {
        wd_state.mode = WD_OFF;
        wd_state.high_cycles = 0U;
        wd_state.low_cycles = 0U;
        wd_state.elapsed = 0U;
    }
    break;
case WD_FAULT:
default:
    wd_state.mode = WD_FAULT;
    wd_state.high_cycles = 0U;
    wd_state.low_cycles = 0U;
    wd_state.elapsed = 0U;
    break;
}

if ((wd_state.mode == WD_DUMPING) || (wd_state.mode == WD_COOLDOWN)) {
    if (adcs_momentum_unload_dipole(&dumpable, wd_input.field_body_t, wd_config.gain_s_inv,
                                    wd_config.max_dipole_a_m2, &cmd, &torque) != ADCS_OK) {
        wd_state.mode = WD_FAULT;
        wd_state.high_cycles = 0U;
        wd_state.low_cycles = 0U;
        wd_state.elapsed = 0U;
        wd_output.mode = WD_FAULT;
        wd_output.momentum_nms = (adcs_vec3_t){0, 0, 0};
        wd_output.parallel_momentum_nms = (adcs_vec3_t){0, 0, 0};
        wd_output.dumpable_momentum_nms = (adcs_vec3_t){0, 0, 0};
        wd_output.dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
        wd_output.torque_nm = (adcs_vec3_t){0, 0, 0};
        wd_output.dumpable_magnitude_nms = 0.0;
        wd_output.high_cycles = 0U;
        wd_output.low_cycles = 0U;
        wd_output.elapsed = 0U;
        wd_output.saturation_mask = 0U;
        return;
    }
} else {
    cmd.command = (adcs_vec3_t){0, 0, 0};
    cmd.saturated_axes = 0U;
    torque = (adcs_vec3_t){0, 0, 0};
}

if (wd_state.mode == WD_FAULT) {
    wd_output.mode = WD_FAULT;
    wd_output.momentum_nms = (adcs_vec3_t){0, 0, 0};
    wd_output.parallel_momentum_nms = (adcs_vec3_t){0, 0, 0};
    wd_output.dumpable_momentum_nms = (adcs_vec3_t){0, 0, 0};
    wd_output.dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
    wd_output.torque_nm = (adcs_vec3_t){0, 0, 0};
    wd_output.dumpable_magnitude_nms = 0.0;
    wd_output.high_cycles = 0U;
    wd_output.low_cycles = 0U;
    wd_output.elapsed = 0U;
    wd_output.saturation_mask = 0U;
} else {
    wd_output.mode = wd_state.mode;
    wd_output.momentum_nms = h;
    wd_output.parallel_momentum_nms = parallel_part;
    wd_output.dumpable_momentum_nms = dumpable;
    wd_output.dipole_a_m2 = cmd.command;
    wd_output.torque_nm = torque;
    wd_output.dumpable_magnitude_nms = dumpable_mag;
    wd_output.high_cycles = wd_state.high_cycles;
    wd_output.low_cycles = wd_state.low_cycles;
    wd_output.elapsed = wd_state.elapsed;
    wd_output.saturation_mask = cmd.saturated_axes;
}

