        adcs_actuator_command_t cmd;
        cmd.command = (adcs_vec3_t){0, 0, 0};
        cmd.saturated_axes = 0U;
        st = adcs_momentum_unload_dipole(&dumpable_vec, wd_input.field_body_t,
